-- RootSolo shared foundation. Apply once through a migration runner, in a transaction.
-- Prerequisite: Supabase auth.users/auth.uid(), anon/authenticated/service_role roles.
-- Does not mutate legacy user_profiles/subscriptions or provision any member balance.
BEGIN;

CREATE TABLE public.ecosystem_projects (
  id text PRIMARY KEY CHECK (id ~ '^[a-z][a-z0-9_]{1,31}$'),
  display_name text NOT NULL,
  enabled boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now()
);
INSERT INTO public.ecosystem_projects(id, display_name) VALUES
 ('platform','1037Solo Platform'),('studyflow','StudyFlow'),('studysolo','StudySolo'),
 ('chatsolo','1037Solo-STEMChatSolo'),('kitsolo','KitSolo'),('account','1037Solo Account'),('landing','1037Solo');

CREATE TABLE public.membership_plans (
  id text PRIMARY KEY,
  storage_bytes bigint NOT NULL CHECK (storage_bytes BETWEEN 0 AND 9007199254740991),
  monthly_microcredits bigint NOT NULL DEFAULT 0 CHECK (monthly_microcredits BETWEEN 0 AND 9007199254740991),
  enabled boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now()
);
-- No automatic money/credits created by these catalog defaults. Import existing grants separately.
INSERT INTO public.membership_plans(id,storage_bytes) VALUES
 ('free',1073741824),('pro',10737418240),('pro_plus',53687091200),('ultra',214748364800);
CREATE TABLE public.project_entitlement_defaults (
  plan_id text NOT NULL REFERENCES public.membership_plans(id),
  project_id text NOT NULL REFERENCES public.ecosystem_projects(id),
  limits jsonb NOT NULL CHECK(jsonb_typeof(limits) = 'object'),
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY(plan_id,project_id)
);
CREATE INDEX project_entitlement_defaults_project_idx ON public.project_entitlement_defaults(project_id);
INSERT INTO public.project_entitlement_defaults(plan_id,project_id,limits) VALUES
 ('free','studyflow','{"workflows":10,"daily_chat_requests":100,"daily_workflow_runs":20,"loop_iterations":5,"concurrency":1}'),
 ('pro','studyflow','{"workflows":50,"daily_chat_requests":200,"daily_workflow_runs":50,"loop_iterations":20,"concurrency":2}'),
 ('pro_plus','studyflow','{"workflows":200,"daily_chat_requests":500,"daily_workflow_runs":150,"loop_iterations":100,"concurrency":4}'),
 ('ultra','studyflow','{"workflows":9999999,"daily_chat_requests":2000,"daily_workflow_runs":500,"loop_iterations":9999999,"concurrency":8}');

CREATE TABLE public.membership_accounts (
  user_id uuid PRIMARY KEY REFERENCES auth.users(id),
  plan_id text NOT NULL DEFAULT 'free' REFERENCES public.membership_plans(id),
  expires_at timestamptz,
  source_reference text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CHECK(plan_id = 'free' OR expires_at IS NOT NULL)
);
CREATE INDEX membership_accounts_plan_idx ON public.membership_accounts(plan_id);
CREATE TABLE public.user_project_entitlements (
  user_id uuid NOT NULL REFERENCES auth.users(id),
  project_id text NOT NULL REFERENCES public.ecosystem_projects(id),
  limits jsonb NOT NULL CHECK(jsonb_typeof(limits) = 'object'),
  expires_at timestamptz NOT NULL,
  source_reference text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY(user_id,project_id)
);
CREATE INDEX user_project_entitlements_project_idx ON public.user_project_entitlements(project_id);

CREATE TABLE public.credit_accounts (
  user_id uuid PRIMARY KEY REFERENCES auth.users(id),
  available_microcredits bigint NOT NULL DEFAULT 0 CHECK(available_microcredits >= 0),
  held_microcredits bigint NOT NULL DEFAULT 0 CHECK(held_microcredits >= 0),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CHECK(available_microcredits::numeric+held_microcredits::numeric <= 9007199254740991)
);
CREATE TABLE public.credit_operations (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES public.credit_accounts(user_id),
  project_id text NOT NULL REFERENCES public.ecosystem_projects(id),
  request_key text NOT NULL CHECK(length(request_key) BETWEEN 1 AND 200),
  state text NOT NULL CHECK(state IN ('reserved','settled','cancelled','refunded','credited')),
  reserved_microcredits bigint NOT NULL DEFAULT 0 CHECK(reserved_microcredits >= 0),
  charged_microcredits bigint NOT NULL DEFAULT 0 CHECK(charged_microcredits >= 0),
  granted_microcredits bigint NOT NULL DEFAULT 0 CHECK(granted_microcredits >= 0),
  metadata jsonb NOT NULL DEFAULT '{}' CHECK(jsonb_typeof(metadata) = 'object'),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(user_id,project_id,request_key),
  CHECK(charged_microcredits <= reserved_microcredits)
);
CREATE INDEX credit_operations_project_idx ON public.credit_operations(project_id);
CREATE INDEX credit_operations_pending_idx ON public.credit_operations(created_at) WHERE state='reserved';
CREATE TABLE public.credit_ledger (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  operation_id uuid NOT NULL REFERENCES public.credit_operations(id),
  user_id uuid NOT NULL REFERENCES auth.users(id),
  event text NOT NULL CHECK(event IN ('grant','reserve','settle','cancel','refund')),
  available_delta bigint NOT NULL,
  held_delta bigint NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(operation_id,event)
);
CREATE INDEX credit_ledger_owner_page_idx ON public.credit_ledger(user_id,id DESC);

CREATE TABLE public.storage_accounts (
  user_id uuid PRIMARY KEY REFERENCES auth.users(id),
  used_bytes bigint NOT NULL DEFAULT 0 CHECK(used_bytes >= 0),
  reserved_bytes bigint NOT NULL DEFAULT 0 CHECK(reserved_bytes >= 0),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CHECK(used_bytes::numeric+reserved_bytes::numeric <= 9007199254740991)
);
CREATE TABLE public.storage_objects (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES public.storage_accounts(user_id),
  project_id text NOT NULL REFERENCES public.ecosystem_projects(id),
  request_key text NOT NULL CHECK(length(request_key) BETWEEN 1 AND 200),
  provider text NOT NULL CHECK(provider IN ('supabase','cos','server')),
  bucket text NOT NULL CHECK(length(bucket)>0),
  object_key text NOT NULL CHECK(length(object_key)>0),
  state text NOT NULL CHECK(state IN ('reserved','committed','cancelled','released')),
  reserved_bytes bigint NOT NULL CHECK(reserved_bytes >= 0),
  size_bytes bigint NOT NULL DEFAULT 0 CHECK(size_bytes >= 0 AND size_bytes <= reserved_bytes),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(user_id,project_id,request_key),
  UNIQUE(provider,bucket,object_key)
);
CREATE INDEX storage_objects_project_idx ON public.storage_objects(project_id);
CREATE INDEX storage_objects_pending_idx ON public.storage_objects(created_at) WHERE state='reserved';
CREATE TABLE public.asset_index (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES auth.users(id),
  project_id text NOT NULL REFERENCES public.ecosystem_projects(id),
  source_type text NOT NULL,
  source_id text NOT NULL,
  title text NOT NULL,
  media_type text,
  source_path text NOT NULL CHECK(source_path LIKE '/%' AND source_path NOT LIKE '//%'),
  storage_object_id uuid REFERENCES public.storage_objects(id),
  metadata jsonb NOT NULL DEFAULT '{}' CHECK(jsonb_typeof(metadata)='object'),
  archived_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(project_id,source_type,source_id)
);
CREATE INDEX asset_index_owner_page_idx ON public.asset_index(user_id,updated_at DESC,id);
CREATE INDEX asset_index_storage_idx ON public.asset_index(storage_object_id);

CREATE TABLE public.tool_submissions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES auth.users(id),
  title text NOT NULL CHECK(length(title) BETWEEN 1 AND 200),
  url text NOT NULL CHECK(url ~ '^https://'),
  description text NOT NULL DEFAULT '',
  state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','approved','rejected')),
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX tool_submissions_owner_idx ON public.tool_submissions(user_id,created_at DESC);
CREATE INDEX tool_submissions_queue_idx ON public.tool_submissions(created_at) WHERE state='pending';
CREATE TABLE public.tool_reviews (
  submission_id uuid PRIMARY KEY REFERENCES public.tool_submissions(id),
  reviewer_id uuid NOT NULL REFERENCES auth.users(id),
  decision text NOT NULL CHECK(decision IN ('approved','rejected')),
  reason text NOT NULL,
  reward_microcredits bigint NOT NULL CHECK(reward_microcredits >= 0),
  reward_operation_id uuid REFERENCES public.credit_operations(id),
  created_at timestamptz NOT NULL DEFAULT now(),
  CHECK(decision='approved' OR reward_microcredits=0)
);
CREATE INDEX tool_reviews_reviewer_idx ON public.tool_reviews(reviewer_id);
CREATE INDEX tool_reviews_reward_idx ON public.tool_reviews(reward_operation_id);

CREATE TABLE public.payment_settings (
  singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),
  live_payments_enabled boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
INSERT INTO public.payment_settings(singleton) VALUES(true);
CREATE TABLE public.payment_orders (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES auth.users(id),
  request_key text NOT NULL,
  product_code text NOT NULL,
  amount_minor bigint NOT NULL CHECK(amount_minor BETWEEN 1 AND 9007199254740991),
  currency text NOT NULL DEFAULT 'CNY' CHECK(currency='CNY'),
  mode text NOT NULL CHECK(mode IN ('test','live')),
  state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','paid','cancelled','refunded')),
  provider text,
  provider_transaction_id text,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(user_id,request_key),
  UNIQUE(provider,provider_transaction_id)
);

-- Only DB privileges authenticate the RPC caller, never a supplied user role/metadata field.
-- The caller server must derive p_user_id from its verified Supabase session.
CREATE FUNCTION public.credit_apply(p_user_id uuid,p_project_id text,p_request_key text,p_action text,p_amount bigint,p_metadata jsonb DEFAULT '{}')
RETURNS public.credit_operations LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE a public.credit_accounts; o public.credit_operations; da bigint:=0; dh bigint:=0;
BEGIN
  IF p_amount IS NULL OR p_amount<0 OR p_amount>9007199254740991 OR p_action IS NULL OR p_action NOT IN ('grant','reserve','settle','cancel','refund') THEN
    RAISE EXCEPTION 'invalid_credit_request' USING ERRCODE='22023'; END IF;
  IF p_metadata IS NULL OR jsonb_typeof(p_metadata)<>'object' THEN RAISE EXCEPTION 'invalid_metadata'; END IF;
  IF p_action IN ('grant','reserve') AND p_amount=0 THEN RAISE EXCEPTION 'amount_must_be_positive'; END IF;
  IF p_action IN ('cancel','refund') AND p_amount<>0 THEN RAISE EXCEPTION 'amount_must_be_zero'; END IF;
  INSERT INTO public.credit_accounts(user_id) VALUES(p_user_id) ON CONFLICT DO NOTHING;
  SELECT * INTO STRICT a FROM public.credit_accounts WHERE user_id=p_user_id FOR UPDATE;
  SELECT * INTO o FROM public.credit_operations WHERE user_id=p_user_id AND project_id=p_project_id AND request_key=p_request_key;
  IF FOUND THEN
    IF (p_action='grant' AND o.state='credited' AND o.granted_microcredits=p_amount AND o.metadata=p_metadata)
       OR (p_action='reserve' AND o.state<>'credited' AND o.reserved_microcredits=p_amount AND o.metadata=p_metadata)
       OR (p_action='settle' AND o.state IN ('settled','refunded') AND o.charged_microcredits=p_amount)
       OR (p_action='cancel' AND o.state='cancelled') OR (p_action='refund' AND o.state='refunded') THEN RETURN o; END IF;
    IF p_action IN ('reserve','grant') THEN RAISE EXCEPTION 'idempotency_conflict'; END IF;
    IF p_action='settle' AND o.state='reserved' THEN
      IF p_amount>o.reserved_microcredits THEN RAISE EXCEPTION 'settlement_exceeds_reservation'; END IF;
      da:=o.reserved_microcredits-p_amount; dh:=-o.reserved_microcredits;
      UPDATE public.credit_operations SET state='settled',charged_microcredits=p_amount,updated_at=now() WHERE id=o.id RETURNING * INTO o;
    ELSIF p_action='cancel' AND o.state='reserved' THEN
      da:=o.reserved_microcredits; dh:=-o.reserved_microcredits;
      UPDATE public.credit_operations SET state='cancelled',updated_at=now() WHERE id=o.id RETURNING * INTO o;
    ELSIF p_action='refund' AND o.state='settled' THEN
      da:=o.charged_microcredits;
      UPDATE public.credit_operations SET state='refunded',updated_at=now() WHERE id=o.id RETURNING * INTO o;
    ELSE RAISE EXCEPTION 'invalid_credit_transition'; END IF;
  ELSE
    IF p_action NOT IN ('grant','reserve') THEN RAISE EXCEPTION 'credit_operation_not_found'; END IF;
    IF p_action='reserve' AND a.available_microcredits<p_amount THEN RAISE EXCEPTION 'insufficient_credits'; END IF;
    IF p_action='reserve' AND NOT EXISTS(SELECT 1 FROM public.ecosystem_projects WHERE id=p_project_id AND enabled) THEN RAISE EXCEPTION 'project_disabled'; END IF;
    da:=CASE WHEN p_action='grant' THEN p_amount ELSE -p_amount END;
    dh:=CASE WHEN p_action='reserve' THEN p_amount ELSE 0 END;
    INSERT INTO public.credit_operations(user_id,project_id,request_key,state,reserved_microcredits,granted_microcredits,metadata)
      VALUES(p_user_id,p_project_id,p_request_key,CASE WHEN p_action='grant' THEN 'credited' ELSE 'reserved' END,
        CASE WHEN p_action='reserve' THEN p_amount ELSE 0 END,CASE WHEN p_action='grant' THEN p_amount ELSE 0 END,p_metadata) RETURNING * INTO o;
  END IF;
  UPDATE public.credit_accounts SET available_microcredits=available_microcredits+da,held_microcredits=held_microcredits+dh,updated_at=now() WHERE user_id=p_user_id;
  INSERT INTO public.credit_ledger(operation_id,user_id,event,available_delta,held_delta) VALUES(o.id,p_user_id,p_action,da,dh);
  RETURN o;
END $$;

CREATE FUNCTION public.storage_apply(p_user_id uuid,p_project_id text,p_request_key text,p_action text,p_bytes bigint,
  p_provider text DEFAULT NULL,p_bucket text DEFAULT NULL,p_object_key text DEFAULT NULL)
RETURNS public.storage_objects LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE a public.storage_accounts; o public.storage_objects; capacity bigint; du bigint:=0; dr bigint:=0;
BEGIN
  IF p_bytes IS NULL OR p_bytes<0 OR p_bytes>9007199254740991 OR p_action IS NULL OR p_action NOT IN ('reserve','commit','cancel','release') THEN RAISE EXCEPTION 'invalid_storage_request'; END IF;
  IF p_action IN ('cancel','release') AND p_bytes<>0 THEN RAISE EXCEPTION 'bytes_must_be_zero'; END IF;
  INSERT INTO public.storage_accounts(user_id) VALUES(p_user_id) ON CONFLICT DO NOTHING;
  SELECT * INTO STRICT a FROM public.storage_accounts WHERE user_id=p_user_id FOR UPDATE;
  SELECT * INTO o FROM public.storage_objects WHERE user_id=p_user_id AND project_id=p_project_id AND request_key=p_request_key;
  IF FOUND THEN
    IF p_action='reserve' THEN
      IF o.reserved_bytes=p_bytes AND o.provider=p_provider AND o.bucket=p_bucket AND o.object_key=p_object_key THEN RETURN o; END IF;
      RAISE EXCEPTION 'idempotency_conflict';
    END IF;
    IF (p_action='commit' AND o.state IN ('committed','released') AND o.size_bytes=p_bytes)
      OR (p_action='cancel' AND o.state='cancelled') OR (p_action='release' AND o.state='released') THEN RETURN o; END IF;
    IF p_action='commit' AND o.state='reserved' THEN
      IF p_bytes>o.reserved_bytes THEN RAISE EXCEPTION 'upload_exceeds_reservation'; END IF;
      du:=p_bytes; dr:=-o.reserved_bytes;
      UPDATE public.storage_objects SET state='committed',size_bytes=p_bytes,updated_at=now() WHERE id=o.id RETURNING * INTO o;
    ELSIF p_action='cancel' AND o.state='reserved' THEN
      dr:=-o.reserved_bytes;
      UPDATE public.storage_objects SET state='cancelled',updated_at=now() WHERE id=o.id RETURNING * INTO o;
    ELSIF p_action='release' AND o.state='committed' THEN
      du:=-o.size_bytes;
      UPDATE public.storage_objects SET state='released',updated_at=now() WHERE id=o.id RETURNING * INTO o;
    ELSE RAISE EXCEPTION 'invalid_storage_transition'; END IF;
  ELSE
    IF p_action<>'reserve' THEN RAISE EXCEPTION 'storage_operation_not_found'; END IF;
    IF NOT EXISTS(SELECT 1 FROM public.ecosystem_projects WHERE id=p_project_id AND enabled) THEN RAISE EXCEPTION 'project_disabled'; END IF;
    SELECT storage_bytes INTO STRICT capacity FROM public.membership_plans WHERE id=coalesce(
      (SELECT plan_id FROM public.membership_accounts WHERE user_id=p_user_id AND (plan_id='free' OR expires_at>now())), 'free');
    IF a.used_bytes::numeric+a.reserved_bytes::numeric+p_bytes::numeric>capacity THEN RAISE EXCEPTION 'storage_quota_exceeded'; END IF;
    dr:=p_bytes;
    INSERT INTO public.storage_objects(user_id,project_id,request_key,provider,bucket,object_key,state,reserved_bytes)
      VALUES(p_user_id,p_project_id,p_request_key,p_provider,p_bucket,p_object_key,'reserved',p_bytes) RETURNING * INTO o;
  END IF;
  UPDATE public.storage_accounts SET used_bytes=used_bytes+du,reserved_bytes=reserved_bytes+dr,updated_at=now() WHERE user_id=p_user_id;
  RETURN o;
END $$;

CREATE FUNCTION public.review_tool(p_submission_id uuid,p_reviewer_id uuid,p_decision text,p_reason text,p_reward_microcredits bigint)
RETURNS public.tool_reviews LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE s public.tool_submissions; r public.tool_reviews; op public.credit_operations;
BEGIN
  IF p_decision IS NULL OR p_decision NOT IN ('approved','rejected') OR p_reward_microcredits IS NULL OR p_reward_microcredits<0
     OR (p_decision='rejected' AND p_reward_microcredits<>0) THEN RAISE EXCEPTION 'invalid_review'; END IF;
  SELECT * INTO STRICT s FROM public.tool_submissions WHERE id=p_submission_id FOR UPDATE;
  IF p_reviewer_id=s.user_id THEN RAISE EXCEPTION 'self_review_forbidden'; END IF;
  SELECT * INTO r FROM public.tool_reviews WHERE submission_id=p_submission_id;
  IF FOUND THEN
    IF r.reviewer_id=p_reviewer_id AND r.decision=p_decision AND r.reason=p_reason AND r.reward_microcredits=p_reward_microcredits THEN RETURN r; END IF;
    RAISE EXCEPTION 'review_already_final';
  END IF;
  IF s.state<>'pending' THEN RAISE EXCEPTION 'submission_not_pending'; END IF;
  IF p_reward_microcredits>0 THEN
    op:=public.credit_apply(s.user_id,'kitsolo','tool-review:'||s.id::text,'grant',p_reward_microcredits,jsonb_build_object('submission_id',s.id));
  END IF;
  INSERT INTO public.tool_reviews(submission_id,reviewer_id,decision,reason,reward_microcredits,reward_operation_id)
    VALUES(s.id,p_reviewer_id,p_decision,p_reason,p_reward_microcredits,op.id) RETURNING * INTO r;
  UPDATE public.tool_submissions SET state=p_decision WHERE id=s.id;
  RETURN r;
END $$;

-- Prevent an accidental live order even through privileged table writes. Test orders never credit wallets.
CREATE FUNCTION public.payment_live_guard() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$
BEGIN
  IF NEW.mode='live' AND NOT coalesce((SELECT live_payments_enabled FROM public.payment_settings WHERE singleton),false) THEN
    RAISE EXCEPTION 'live_payments_disabled'; END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER payment_live_guard BEFORE INSERT OR UPDATE ON public.payment_orders FOR EACH ROW EXECUTE FUNCTION public.payment_live_guard();

-- Ensure an attached object belongs to the asset owner; never accept a caller-provided cross-user ID.
CREATE FUNCTION public.asset_owner_guard() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$
BEGIN
  IF NEW.storage_object_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.storage_objects WHERE id=NEW.storage_object_id AND user_id=NEW.user_id AND state='committed') THEN
    RAISE EXCEPTION 'asset_storage_owner_mismatch'; END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER asset_owner_guard BEFORE INSERT OR UPDATE ON public.asset_index FOR EACH ROW EXECUTE FUNCTION public.asset_owner_guard();

-- Active plan resolves on every read; expiry does not require a cron to enforce the free tier.
CREATE FUNCTION public.ecosystem_entitlements(p_user_id uuid) RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
  WITH active_plan AS (
    SELECT coalesce((SELECT plan_id FROM public.membership_accounts WHERE user_id=p_user_id
      AND (plan_id='free' OR expires_at>now())), 'free') AS id
  ) SELECT jsonb_build_object(
    'plan_id',p.id,'storage_bytes',p.storage_bytes::text,'monthly_microcredits',p.monthly_microcredits::text,
    'projects',coalesce((SELECT jsonb_object_agg(e.id,
       coalesce(d.limits,'{}'::jsonb) || coalesce(o.limits,'{}'::jsonb))
       FROM public.ecosystem_projects e
       LEFT JOIN public.project_entitlement_defaults d ON d.project_id=e.id AND d.plan_id=p.id
       LEFT JOIN public.user_project_entitlements o ON o.project_id=e.id AND o.user_id=p_user_id AND o.expires_at>now()
       WHERE e.enabled),'{}'::jsonb))
    FROM public.membership_plans p JOIN active_plan a ON a.id=p.id;
$$;
CREATE FUNCTION public.my_ecosystem_entitlements() RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication_required' USING ERRCODE='42501'; END IF;
  RETURN public.ecosystem_entitlements(auth.uid());
END $$;

-- Supabase may have permissive default ACLs: explicitly remove mutation privileges and PUBLIC RPC execution.
DO $$ DECLARE t text; BEGIN
  FOREACH t IN ARRAY ARRAY['ecosystem_projects','membership_plans','project_entitlement_defaults','membership_accounts','user_project_entitlements',
    'credit_accounts','credit_operations','credit_ledger','storage_accounts','storage_objects','asset_index','tool_submissions','tool_reviews','payment_settings','payment_orders'] LOOP
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);
    EXECUTE format('REVOKE ALL ON public.%I FROM PUBLIC,anon,authenticated',t);
    EXECUTE format('GRANT SELECT,INSERT,UPDATE ON public.%I TO service_role',t);
    EXECUTE format('COMMENT ON TABLE public.%I IS %L',t,'【Shared RootSolo】'||t||' — unified ecosystem foundation; server-owned writes');
  END LOOP;
  FOREACH t IN ARRAY ARRAY['membership_accounts','user_project_entitlements','credit_accounts','credit_operations','credit_ledger','storage_accounts','storage_objects','asset_index','tool_submissions','payment_orders'] LOOP
    EXECUTE format('GRANT SELECT ON public.%I TO authenticated',t);
    EXECUTE format('CREATE POLICY owner_read ON public.%I FOR SELECT TO authenticated USING(user_id=(SELECT auth.uid()))',t);
  END LOOP;
  FOREACH t IN ARRAY ARRAY['ecosystem_projects','membership_plans','project_entitlement_defaults'] LOOP
    EXECUTE format('GRANT SELECT ON public.%I TO anon,authenticated',t);
    EXECUTE format('CREATE POLICY catalog_read ON public.%I FOR SELECT TO anon,authenticated USING(true)',t);
  END LOOP;
END $$;
REVOKE ALL ON FUNCTION public.credit_apply(uuid,text,text,text,bigint,jsonb),
  public.storage_apply(uuid,text,text,text,bigint,text,text,text),public.review_tool(uuid,uuid,text,text,bigint),
  public.payment_live_guard(),public.asset_owner_guard(),public.ecosystem_entitlements(uuid),public.my_ecosystem_entitlements()
  FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.credit_apply(uuid,text,text,text,bigint,jsonb),public.storage_apply(uuid,text,text,text,bigint,text,text,text),public.review_tool(uuid,uuid,text,text,bigint) TO service_role;
GRANT EXECUTE ON FUNCTION public.ecosystem_entitlements(uuid) TO service_role;
GRANT EXECUTE ON FUNCTION public.my_ecosystem_entitlements() TO authenticated;
GRANT USAGE,SELECT ON SEQUENCE public.credit_ledger_id_seq TO service_role;
-- Wallet/operation tables can only be mutated atomically via RPC, even by the application service role.
REVOKE INSERT,UPDATE ON public.credit_accounts,public.credit_operations,public.credit_ledger,public.storage_accounts,public.storage_objects,public.tool_reviews FROM service_role;

COMMIT;
